const routeLinks=[...document.querySelectorAll('[data-route]')];
function openProject(id,expanded=true){const row=document.getElementById(id);if(!row)return;const button=row.querySelector('.project-toggle');button.setAttribute('aria-expanded',String(expanded));row.querySelector('.project-detail').hidden=!expanded;button.querySelector('.plus').textContent=expanded?'−':'+';}
function route(){let [page,project]=location.hash.slice(1).split('/');if(page==='work')page='projects';if(!['about','projects','experience','art'].includes(page))page='about';document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==page);routeLinks.forEach(a=>{if(a.dataset.route===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=page==='about'?'abhiram nutakki':`${page} · abhiram nutakki`;if(page==='projects'&&project)openProject(project);}
window.addEventListener('hashchange',route);document.querySelectorAll('.project-toggle').forEach(b=>b.addEventListener('click',()=>openProject(b.closest('article').id,b.getAttribute('aria-expanded')!=='true')));
route();
